{
  "criteria": [
    {
      "id": "C1",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Introduction",
          "quote": "The spacecraft is intended to image and send data to ground stations for collation and analysis."
        },
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required."
        },
        {
          "where": "Introduction",
          "quote": "The proposed satellite would likely be used by governmental and science agencies (e.g. CSIRO, BOM) for research and/or education."
        }
      ],
      "reasoning": "The mission purpose, Australian conservation rationale, single-spacecraft choice, and likely users are explained. However, the operator and paying or operational customers are not clearly distinguished or assigned, and the mission rationale lacks supporting literature for some claims."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Launch",
          "quote": "The proposed satellite will thus use the Vega E rocket as a launch vehicle – launched from the Guiana Space Centre Spaceport."
        },
        {
          "where": "Orbit",
          "quote": "Specifically, an altitude of 600km requires a mean inclination of $ 97.7924^{\\circ} $ for the satellite to remain sun-synchronous."
        },
        {
          "where": "Orbit",
          "quote": "The orbit is circular and thus has no perigee."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "Systems Tool Kit 11 (STK) was used to calculate access periods as seen below:"
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "The most promising alternative is a ‘drag sail’ – a drag-enhancing deorbit device that deploys at the EOL."
        },
        {
          "where": "Image 3",
          "quote": ""
        }
      ],
      "reasoning": "The report addresses launch choice, orbit and elements, manoeuvres, ground station access, duration, and EOL, with STK outputs and screenshots. However, the mission design is weakly supported in key areas: payload and imaging feasibility, reef revisit, communications link, launch implementation, and EOL decay time are not quantified. Some orbit and sunlight claims are technically misleading."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "A polar sun-synchronous orbit allows for consistent illumination of the oceans while maintaining a constant sun angle."
        },
        {
          "where": "Conclusion",
          "quote": "Thus, launch may need to be adjusted if the rocket is still not constructed by the proposed date."
        }
      ],
      "reasoning": "The conclusion recaps the selected architecture and identifies a launch-vehicle contingency. It is relevant but mostly summarizes choices rather than drawing detailed conclusions from the evidence or acknowledging major uncertainties in imaging performance, coverage, and EOL."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Image 4",
          "quote": ""
        },
        {
          "where": "Bibliography",
          "quote": "https://en.wikipedia.org/wiki/2021_in_spaceflight. [Online]."
        }
      ],
      "reasoning": "The report has a recognizable, logical structure and an executive summary, and the main text is generally understandable. Presentation is not professional: grammar and wording errors occur, figures and tables are not consistently numbered and titled, and the reference list is incomplete and inconsistent with some in-text citations; Wikipedia is used as a source."
    }
  ],
